        title: t.title,
        subtitle: `${t.chapterId} \xB7 ${t.theoremStatement.slice(0, 75)}... \xB7 ${t.marksWeightage} Marks`,
        badge: "Math",
        route: "derivations",
        keywords: [t.title, t.chapterId, "math", "theorem", "proof"]
