function timetable(list, blocks, d) {
  const hours = [];
  const first = Math.min(d ? Math.floor(minute(d.start) / 60) : 8, ...list.filter((t) => t.time).map((t) => Math.floor(minute(t.time) / 60)), ...blocks.map((b) => Math.floor(b.a / 60)));
  const end = Math.max(d ? Math.ceil(minute(d.end) / 60) : 22, ...list.filter((t) => t.time).map((t) => Math.ceil((minute(t.time) + t.minutes) / 60)), ...blocks.map((b) => Math.ceil(b.b / 60)));
  for (let h = first; h < end; h++) {
    const time4 = clock(d && h === Math.floor(minute(d.start) / 60) ? Math.max(h * 60, minute(d.start)) : h * 60), here = blocks.filter((b) => Math.floor(b.a / 60) === h), items = list.filter((t) => t.time && Math.floor(minute(t.time) / 60) === h);
    hours.push(`<div class="hour" data-drop="${time4}"><time>${esc3(labelTime(time4))}</time><div>${here.map((b) => `<p class="commitment">${esc3(b.label)}</p>`).join("")}${items.map((t) => row(t)).join("")}${!here.length && !items.length ? tool("slot", "Add task at " + labelTime(time4), "plus", time4) : ""}</div></div>`);
  }
  const late = d?.lateStart && !d.lateEnd ? `<div class="late-window"><div><strong>Later study \xB7 after 9 p.m.</strong><small>No finish time set</small></div>${btn("slot", "Add a later study task", "plus", "outline", d.lateStart)}</div>` : "";
  return hours.join("") + late + (list.some((t) => !t.time) ? "<h3>Any time</h3>" + list.filter((t) => !t.time).map((t) => row(t)).join("") : "");
}
