    if (reason) {
      error(reason);
      const alt = late ? "" : freeSlot(state, item);
      modal.querySelector("#slot-help").innerHTML = alt ? btn("use-slot", "Use " + labelTime(alt), "clock-3", "outline", alt) : "<small>Leave the time blank or pick another window.</small>";
      return;
    }
